<?php $this->load->view('os/resources');
$permission = $this->session->userdata('permissao'); ?>
<div class="os-workspace-v2" data-os-root data-os-base="<?= site_url('os') ?>">
<header class="os-summary"><div class="os-section-heading"><div><span class="mapos-eyebrow">ATENDIMENTOS</span><h1>Ordens de serviço</h1></div><div class="os-action-links"><?php if ($this->permission->checkPermission($permission, 'aOs')) { ?><a class="btn btn-primary" href="<?= site_url('os/adicionar') ?>">Nova ordem de serviço</a><?php } ?><a class="btn" href="<?= site_url('kanban') ?>">Abrir Kanban</a></div></div></header>
<div class="os-feedback" data-os-feedback role="status" aria-live="polite" hidden></div>
<section class="mapos-card"><form method="get" action="<?= site_url('os/gerenciar') ?>">
<div class="os-field-grid"><label for="os-search">Cliente ou número da OS<input id="os-search" name="pesquisa" value="<?= html_escape($this->input->get('pesquisa') ?? '') ?>"></label><label for="os-status-filter">Status<select id="os-status-filter" name="status"><option value="">Todos os status</option><?php foreach (['Aberto', 'Orçamento', 'Negociação', 'Aprovado', 'Aguardando Peças', 'Em Andamento', 'Finalizado', 'Faturado', 'Cancelado'] as $statusOption) { ?><option <?= $this->input->get('status') === $statusOption ? 'selected' : '' ?>><?= html_escape($statusOption) ?></option><?php } ?></select></label><label for="os-date-from">Data inicial a partir de<input id="os-date-from" class="datepicker" autocomplete="off" name="data" placeholder="dd/mm/aaaa" value="<?= html_escape($this->input->get('data') ?? '') ?>"></label><label for="os-date-to">Até<input id="os-date-to" class="datepicker" autocomplete="off" name="data2" placeholder="dd/mm/aaaa" value="<?= html_escape($this->input->get('data2') ?? '') ?>"></label></div><div class="os-form-actions"><button type="submit" class="btn btn-primary">Filtrar OS</button><a class="btn" href="<?= site_url('os') ?>">Limpar filtros</a></div></form></section>
<section class="mapos-card"><div class="mapos-table-scroll"><table class="table table-bordered"><thead><tr><th>OS / cliente</th><th>Responsável</th><th>Datas</th><th>Itens</th><th>Desconto</th><th>Total a pagar</th><th>Status</th><th>Ações</th></tr></thead><tbody>
<?php foreach ($results as $order) {
    $gross = round($order->totalProdutos + $order->totalServicos, 2);
    $net = $order->tipo_desconto ? (float) $order->valor_desconto : $gross;
    $editable = $this->os_model->isEditable($order->idOs);
    ?>
<tr><td><strong>#<?= (int) $order->idOs ?></strong><br><?= html_escape($order->nomeCliente) ?></td><td><?= html_escape($order->nome) ?></td><td><?= html_escape(date('d/m/Y', strtotime($order->dataInicial))) ?><br><small>Final prevista: <?= $order->dataFinal ? html_escape(date('d/m/Y', strtotime($order->dataFinal))) : 'Não informada' ?></small><?php if ((int) $order->garantia > 0) { ?><br><small>Garantia: <?= (int) $order->garantia ?> dias</small><?php } ?></td><td>R$ <?= html_escape(number_format($gross, 2, ',', '.')) ?></td><td>R$ <?= html_escape(number_format($gross - $net, 2, ',', '.')) ?></td><td><strong>R$ <?= html_escape(number_format($net, 2, ',', '.')) ?></strong><?php if ($order->faturado) { ?><br><small>Lançamento registrado</small><?php } ?></td><td><span class="mapos-pill"><?= html_escape($order->status) ?></span></td><td><div class="os-list-actions"><a class="btn btn-small" href="<?= site_url('os/visualizar/' . (int) $order->idOs) ?>">Consultar</a><?php if ($editable && $this->permission->checkPermission($permission, 'eOs')) { ?><a class="btn btn-small" href="<?= site_url('os/editar/' . (int) $order->idOs) ?>">Editar</a><?php } ?><a class="btn btn-small" href="<?= site_url('os/imprimir/' . (int) $order->idOs) ?>" target="_blank" rel="noopener">Imprimir A4</a><?php if ($editable && $this->permission->checkPermission($permission, 'dOs')) { ?><form action="<?= site_url('os/excluir') ?>" method="post" data-os-confirm="Excluir esta ordem de serviço? Esta ação remove o atendimento."><input type="hidden" name="id" value="<?= (int) $order->idOs ?>"><button type="submit" class="btn btn-danger btn-small">Excluir</button></form><?php } ?></div></td></tr>
<?php } ?><?php if (! $results) { ?><tr><td colspan="8">Nenhuma OS encontrada para estes filtros.</td></tr><?php } ?></tbody></table></div><?= $this->pagination->create_links() ?></section></div>
